"use strict";
/**
 * Echo equipment, rolled once per completed Echo encounter. Each boss's normal loot comes from
 * its own normal path (NpcDrops at its death, the Guardians' table, the Gauntlet chest, Hespori's
 * harvest), as for every other kill of that boss.
 *
 * Rates are the Wiki's (npc-encounter-variants.json `unique_table`, generated by osrsreboxed-db).
 * Demonic Pacts League/Echo bosses and echo equipment: a player who has not received an item
 * gets it on the kill at twice its listed rate (1/30: the 60th). The world's boss rare multiplier
 * (NpcDrops:bossRareMultiplier) applies once; league drop boosts do not, since nothing here
 * passes through npc-drops:chance. The guarantee stays at the listed kill count.
 *
 * Saved per player: Echo completions per boss and the items received, so trading, losing or
 * destroying an item never restarts its guarantee.
 */
const variants = require("../../../data/definitions/npc-encounter-variants.json");

const LOOT_ATTRIBUTE = "echo-boss:loot";
const BOSS_RARE_MULTIPLIER_CONFIG = "NpcDrops:bossRareMultiplier";
const MAX_COUNT = 2147483647;
const EMPTY = Object.freeze({ version: 1, kills: {}, received: {} });

let api = null;

function counts(value) {
  return !!value && typeof value === "object" && !Array.isArray(value);
}

/** The player's saved Echo loot state, or null when it is malformed (never overwritten then). */
function stateOf(player) {
  const saved = player.getAttribute(LOOT_ATTRIBUTE) ?? EMPTY;
  if (saved.version !== 1 || !counts(saved.kills) || !counts(saved.received)) return null;
  if (Object.values(saved.kills).some((count) => !Number.isSafeInteger(count) || count < 0 || count > MAX_COUNT)) return null;
  return saved;
}

/** The boss's Echo equipment rows that can be rolled. */
function uniquesOf(boss) {
  return (variants.bosses?.[boss]?.unique_table?.entries ?? []).filter((entry) =>
    Number.isSafeInteger(entry.item_id) && entry.item_id >= 0 && Number.isSafeInteger(entry.out_of) && entry.out_of > 0);
}

function multiplier() {
  const value = Number(api.getPluginConfig(BOSS_RARE_MULTIPLIER_CONFIG, 1));
  return Number.isFinite(value) && value > 1 ? value : 1;
}

function amountOf(entry, random) {
  const [min, max] = Array.isArray(entry.quantity) ? entry.quantity : [1, 1];
  const low = Number.isSafeInteger(min) && min > 0 ? min : 1;
  const high = Number.isSafeInteger(max) && max >= low ? max : low;
  return high === low ? low : low + Math.floor(random() * (high - low + 1));
}

/** One Echo completion's equipment: each row rolled on its own, guaranteed on the listed kill. */
function rollUniques(boss, killCount, received, random) {
  const drops = [];
  const boost = multiplier();
  for (const entry of uniquesOf(boss)) {
    const key = `${boss}:${entry.item_id}`;
    const guaranteed = received[key] !== true && killCount >= entry.out_of * 2;
    if (guaranteed || random() * entry.out_of < boost) drops.push({ itemId: entry.item_id, amount: amountOf(entry, random), key });
  }
  return drops;
}

/** Puts the equipment where the encounter's normal loot goes. */
function deliver(event, drops) {
  const items = drops.map(({ itemId, amount }) => ({ itemId, amount }));
  if (typeof event.queueReward === "function") { event.queueReward(items); return; }
  if (typeof event.deliver === "function") { event.deliver(items); return; }
  if (!items.length) return;
  const npc = event.npcs?.[0] ?? null;
  api.emitCustomEvent("npc-drops:roll", { player: event.player, npc, npcId: npc?.getId?.(), drops: items, countKill: false, echo: true });
  api.emitCustomEvent("npc-drops:place", { player: event.player, drops: items, location: event.location ?? npc?.getLocation?.() });
}

/**
 * Called by Sessions for a validated, committed completion. Answers { success, killCount }.
 * `random` is for tests.
 */
function complete(event, random = Math.random) {
  const state = stateOf(event.player);
  if (!state) return { success: false };
  const killCount = Math.min(MAX_COUNT, (state.kills[event.boss] ?? 0) + 1);
  const drops = rollUniques(event.boss, killCount, state.received, random);
  const received = { ...state.received };
  for (const drop of drops) received[drop.key] = true;
  event.player.setAttribute(LOOT_ATTRIBUTE, { version: 1, kills: { ...state.kills, [event.boss]: killCount }, received });
  deliver(event, drops);
  api.emitCustomEvent("persistence:save", { player: event.player, reason: "echo-boss-loot" });
  return { success: true, killCount };
}

function attach(pluginApi) {
  api = pluginApi;
  api.persistAttribute(LOOT_ATTRIBUTE, EMPTY);
}

module.exports = { attach, complete, rollUniques, stateOf, LOOT_ATTRIBUTE };
